<?php
require_once __DIR__.'/_auth.php';require_once __DIR__.'/_header.php';
$tot=$conn->query("SELECT COUNT(*) cantidad,COALESCE(SUM(CASE WHEN estado='aprobado' THEN monto ELSE 0 END),0) ingresos,COALESCE(SUM(CASE WHEN estado='aprobado' AND DATE(fecha_pago)=CURDATE() THEN monto ELSE 0 END),0) hoy FROM pagos")->fetch_assoc();
$sem=$conn->query("SELECT COALESCE(SUM(monto),0) total FROM pagos WHERE estado='aprobado' AND fecha_pago>=DATE_SUB(CURDATE(),INTERVAL 6 DAY)")->fetch_assoc()['total'];
$labels=[];$values=[];$q=$conn->query("SELECT DATE(fecha_pago) dia,SUM(monto) total FROM pagos WHERE estado='aprobado' AND fecha_pago>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(fecha_pago)");$map=[];while($r=$q->fetch_assoc())$map[$r['dia']]=$r['total'];
for($i=6;$i>=0;$i--){$d=date('Y-m-d',strtotime("-$i days"));$labels[]=date('d/m',strtotime($d));$values[]=(float)($map[$d]??0);}
$sql="SELECT pg.id,pg.fecha_pago,pg.metodo_pago,pg.monto,pg.estado,pg.referencia,pg.notas,u.name,u.Lname,u.email,p.nombre_plan FROM pagos pg JOIN suscripciones s ON s.id=pg.suscripcion_id JOIN usuarios u ON u.id=s.usuario_id JOIN planes p ON p.id=s.plan_id ORDER BY pg.fecha_pago DESC";
$pagos=$conn->query($sql);adminHeader('Compras','compras');
?>
<div class="row g-3"><div class="col-md-4"><div class="stat-card"><div class="stat-icon"><i class="bi bi-receipt"></i></div><div><small>Pagos registrados</small><strong><?= (int)$tot['cantidad'] ?></strong></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-icon"><i class="bi bi-cash-stack"></i></div><div><small>Ingresos acumulados</small><strong>$<?= number_format((float)$tot['ingresos'],2) ?></strong></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-icon"><i class="bi bi-calendar-day"></i></div><div><small>Ingresos de hoy</small><strong>$<?= number_format((float)$tot['hoy'],2) ?></strong></div></div></div></div>
<section class="content-card"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><h2 class="section-title mb-0">Ingresos de los últimos 7 días</h2><span class="badge badge-soft">Semana: $<?= number_format((float)$sem,2) ?> MXN</span></div><canvas id="incomeChart" height="100"></canvas></section>
<section class="content-card"><h2 class="section-title">Historial de compras</h2><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Compra</th><th>Usuario</th><th>Plan</th><th>Fecha</th><th>Método</th><th>Monto</th><th>Estado</th><th>Referencia / notas</th></tr></thead><tbody>
<?php if($pagos->num_rows):while($p=$pagos->fetch_assoc()):?><tr><td>#<?= (int)$p['id'] ?></td><td><?= htmlspecialchars($p['name'].' '.$p['Lname']) ?><br><small class="text-secondary"><?= htmlspecialchars($p['email']) ?></small></td><td><?= htmlspecialchars($p['nombre_plan']) ?></td><td><?= htmlspecialchars($p['fecha_pago']) ?></td><td><?= htmlspecialchars($p['metodo_pago']) ?></td><td class="fw-bold">$<?= number_format((float)$p['monto'],2) ?></td><td><span class="badge <?= $p['estado']==='aprobado'?'badge-soft':'text-bg-secondary' ?>"><?= htmlspecialchars($p['estado']) ?></span></td><td><small><?= htmlspecialchars($p['referencia']??'—') ?><br><?= htmlspecialchars($p['notas']??'') ?></small></td></tr><?php endwhile;else:?><tr><td colspan="8" class="text-center text-secondary py-4">Todavía no hay compras registradas.</td></tr><?php endif;?></tbody></table></div></section>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>
new Chart(document.getElementById('incomeChart'),{type:'line',data:{labels:<?= json_encode($labels) ?>,datasets:[{label:'Ingresos MXN',data:<?= json_encode($values) ?>,borderColor:'#35b7a0',backgroundColor:'rgba(53,183,160,.14)',fill:true,tension:.35}]},options:{responsive:true,plugins:{legend:{display:true}},scales:{y:{beginAtZero:true,ticks:{callback:v=>'$'+v}}}}});
</script><?php adminFooter(); ?>
